inc := make(chan int)
done := make(chan int)

// A dona: única goroutine que acessa count.
go func() {
	count := 0
	for n := range inc {
		count += n
	}
	done <- count
}()

var wg sync.WaitGroup
for w := 0; w < 8; w++ {
	wg.Add(1)
	go func() {
		defer wg.Done()
		for i := 0; i < 1000; i++ {
			inc <- 1
		}
	}()
}

wg.Wait()
close(inc)
fmt.Println(<-done) // 8000

